import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"Model Context Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/customization/mcp.md","filePath":"zh/kimi-code-cli/customization/mcp.md"}`),a={name:`kimi-code-cli/customization/mcp.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="model-context-protocol" tabindex="-1">Model Context Protocol <a class="header-anchor" href="#model-context-protocol" aria-label="Permalink to “Model Context Protocol”">​</a></h1><p><a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol（MCP）</a> 是一个开放协议，让模型可以安全地调用外部进程或服务暴露的工具——例如读取 GitHub issues、查询数据库、操作本地文件系统。Kimi Code CLI 作为 MCP client 接入这些外部工具，并把它们与内置工具（<code>Read</code>、<code>Bash</code>、<code>Grep</code> 等）一起暴露给 Agent 使用，行为上没有差异。</p><h2 id="接入方式" tabindex="-1">接入方式 <a class="header-anchor" href="#接入方式" aria-label="Permalink to “接入方式”">​</a></h2><p>Kimi Code CLI 支持三种 MCP server 接入方式：</p><ul><li><strong>stdio</strong>：CLI 以子进程方式启动本地 MCP server，通过标准输入输出通信。适合本地命令行工具。</li><li><strong>HTTP</strong>：CLI 连接一个已在运行的 HTTP 端点。适合远程服务或需要持久运行的进程。</li><li><strong>SSE</strong>：CLI 连接旧式 HTTP+SSE 端点（Server-Sent Events，一种流式 HTTP 机制）。新 MCP server 优先使用 HTTP；只有服务仍仅暴露旧式 SSE 传输时，才设置 <code>transport: &quot;sse&quot;</code>。</li></ul><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h2><p>MCP server 配置写在 <code>mcp.json</code> 中，分两层：</p><ul><li><strong>用户级</strong>：<code>~/.kimi-code/mcp.json</code>（或 <code>$KIMI_CODE_HOME/mcp.json</code>），跨项目共享</li><li><strong>项目级</strong>：工作目录下的 <code>.kimi-code/mcp.json</code>，只对当前仓库生效</li></ul><p>同名条目以项目级为准，覆盖用户级。</p><p>在 TUI 中运行 <code>/mcp-config</code> 可以交互式地新增、编辑或删除 server，无需手动编辑 JSON 文件。运行 <code>/mcp</code> 可查看当前所有 server 的连接状态。</p><p><code>mcp.json</code> 的结构：</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@modelcontextprotocol/server-filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/tmp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;linear&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.linear.app/mcp&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;legacy-events&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;transport&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sse&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.example.com/sse&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>含 <code>command</code> 字段的条目为 stdio server；含 <code>url</code> 字段且未写 <code>transport</code> 的条目为 HTTP server。旧式 SSE server 需要显式把 <code>transport</code> 设为 <code>&quot;sse&quot;</code>。</p><p>可选字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>适用方式</th><th>说明</th></tr></thead><tbody><tr><td><code>env</code></td><td><code>Record&lt;string, string&gt;</code></td><td>stdio</td><td>注入子进程的环境变量</td></tr><tr><td><code>cwd</code></td><td><code>string</code></td><td>stdio</td><td>子进程工作目录</td></tr><tr><td><code>headers</code></td><td><code>Record&lt;string, string&gt;</code></td><td>HTTP、SSE</td><td>附加到每次请求的静态请求头</td></tr><tr><td><code>bearerTokenEnvVar</code></td><td><code>string</code></td><td>HTTP、SSE</td><td>存放 bearer token 的环境变量名</td></tr><tr><td><code>enabled</code></td><td><code>boolean</code></td><td>全部</td><td>设为 <code>false</code> 可禁用该 server</td></tr><tr><td><code>startupTimeoutMs</code></td><td><code>number</code></td><td>全部</td><td>连接超时，取值范围为 <code>1</code> 到 <code>2147483647</code> 毫秒，默认 <code>30000</code></td></tr><tr><td><code>toolTimeoutMs</code></td><td><code>number</code></td><td>全部</td><td>单次工具调用超时，取值范围为 <code>1</code> 到 <code>2147483647</code> 毫秒</td></tr><tr><td><code>enabledTools</code></td><td><code>string[]</code></td><td>全部</td><td>工具白名单</td></tr><tr><td><code>disabledTools</code></td><td><code>string[]</code></td><td>全部</td><td>工具黑名单</td></tr></tbody></table><p>连接超时和单次工具调用超时的默认值都不必逐个 server 设置：<code>config.toml</code> 的 <code>[mcp] startup_timeout_ms</code> / <code>[mcp] tool_timeout_ms</code> 或环境变量 <code>KIMI_MCP_STARTUP_TIMEOUT_MS</code> / <code>KIMI_MCP_TOOL_TIMEOUT_MS</code> 可以调整全局默认值，优先级为 server 字段 &gt; 环境变量 &gt; <code>config.toml</code> &gt; 内置默认。详见 <a href="/code/docs/kimi-code-cli/configuration/config-files.html#mcp">配置文件</a>。</p><p>HTTP 与 SSE server 支持通过 <code>headers</code> 或 <code>bearerTokenEnvVar</code> 提供静态凭证。需要 OAuth 时，运行 <code>/mcp-config login &lt;server-name&gt;</code> 完成浏览器授权。</p><p>Plugins 也可以在 manifest 中声明 MCP servers。Plugin 声明的 servers 默认启用，可以在 <code>/plugins</code> 中禁用或重新启用，然后开启新会话。详见 <a href="/code/docs/kimi-code-cli/customization/plugins.html">Plugins</a>。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>项目级 <code>.kimi-code/mcp.json</code> 中的 stdio 条目会在会话启动时执行本地命令，只在你信任的仓库里启用。</p></div><h2 id="工具命名与权限" tabindex="-1">工具命名与权限 <a class="header-anchor" href="#工具命名与权限" aria-label="Permalink to “工具命名与权限”">​</a></h2><p>MCP 工具按 <code>mcp__&lt;server&gt;__&lt;tool&gt;</code> 格式命名，例如 <code>mcp__github__create_issue</code>。权限规则中支持 <code>*</code> 和 <code>**</code> 通配，例如 <code>mcp__github__*</code> 命中该 server 下所有工具。MCP 工具参数不参与权限匹配。</p><p>未命中权限规则的调用会触发审批请求；在审批弹窗中选择&quot;Approve for this session&quot;后，本次会话内的后续同类调用自动放行。</p><p>也可以在 <code>config.toml</code> 的 <code>[[permission.rules]]</code> 中预置永久规则：</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">decision = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allow&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp__github__*&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">decision = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deny&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp__filesystem__write_file&quot;</span></span></code></pre></div><p>权限规则的完整语法见<a href="/code/docs/kimi-code-cli/configuration/config-files.html#permission">配置文件</a>。</p><h2 id="安全性" tabindex="-1">安全性 <a class="header-anchor" href="#安全性" aria-label="Permalink to “安全性”">​</a></h2><p>接入外部 MCP server 时需注意：</p><ul><li>只接入可信来源的 server</li><li>在审批请求中核查工具名与参数是否合理</li><li>对高风险工具（写文件、执行命令等）维持手动审批，避免用 <code>mcp__*</code> 通配放行全部工具</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>在 YOLO 模式下，MCP 工具调用会被自动批准。仅在完全信任所接入的 MCP server 时使用此模式。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/code/docs/kimi-code-cli/customization/plugins.html">Plugins</a> — 在 plugin manifest 中声明 MCP server，一键打包和分发</li><li><a href="/code/docs/kimi-code-cli/configuration/config-files.html#permission">配置文件</a> — 权限规则的完整字段参考</li></ul>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};